const page = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"description\" content=\"Three wedding website concepts for Wilda and Sean Walker.\">\n  <title>Wilda & Sean Walker — Wedding Website Concepts</title>\n  <style>:root{--bg:#f4efe5;--surface:#fffaf0;--ink:#183d30;--muted:#6e766c;--accent:#b99a51;--accent-soft:#d9c58f;--deep:#0a2b20;--line:rgba(24,61,48,.22);--hero-position:center 35%;--serif:Georgia,'Times New Roman',serif;--sans:'Avenir Next',Avenir,Helvetica,Arial,sans-serif}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);transition:background .35s,color .35s}a{color:inherit}img{display:block;width:100%;height:100%;object-fit:cover}button{font:inherit}\n.concept-picker{position:fixed;z-index:20;left:50%;bottom:22px;transform:translateX(-50%);display:flex;align-items:center;gap:14px;padding:9px 10px 9px 16px;background:rgba(255,255,255,.92);color:#171914;border:1px solid rgba(0,0,0,.1);border-radius:100px;box-shadow:0 12px 42px rgba(0,0,0,.2);backdrop-filter:blur(14px)}.picker-label{font-size:10px;letter-spacing:.15em;text-transform:uppercase;white-space:nowrap}.picker-buttons{display:flex;gap:4px}.picker-buttons button{display:flex;align-items:center;gap:7px;border:0;background:transparent;padding:9px 12px;border-radius:100px;cursor:pointer;font-size:11px}.picker-buttons button.active{background:#ebe8e1}.swatch{width:13px;height:13px;border-radius:50%;box-shadow:inset 0 0 0 1px rgba(0,0,0,.15)}.swatch.noir{background:linear-gradient(135deg,#111 50%,#fff 50%)}.swatch.emerald{background:linear-gradient(135deg,#143b2e 50%,#c4a355 50%)}.swatch.sage{background:linear-gradient(135deg,#9ca78c 50%,#e6d5ba 50%)}\n.hero{position:relative;height:100svh;min-height:690px;color:#fff;overflow:hidden}.hero-photo{position:absolute;inset:0;background:url('assets/portrait-stairs.jpeg') var(--hero-position)/cover no-repeat;transform:scale(1.01)}.hero-shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(3,14,10,.58),rgba(3,14,10,.12) 42%,rgba(3,14,10,.72))}.top-nav{position:absolute;z-index:3;top:0;left:0;width:100%;padding:25px 4.5%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.32)}.monogram{text-decoration:none;font-family:var(--serif);font-size:20px;letter-spacing:.12em}.monogram b{color:var(--accent);font-weight:400;font-style:italic}.nav-links{display:flex;gap:35px}.nav-links a,.nav-rsvp{font-size:10px;letter-spacing:.19em;text-transform:uppercase;text-decoration:none}.nav-rsvp{border:1px solid currentColor;padding:11px 21px}.hero-content{position:relative;z-index:2;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:90px 24px 50px}.eyebrow,.section-kicker{font-size:10px;letter-spacing:.32em;text-transform:uppercase;font-weight:600}.hero-content h1{margin:13px 0 8px;font-family:var(--serif);font-size:clamp(63px,11vw,158px);line-height:.7;font-weight:400;letter-spacing:-.06em;text-shadow:0 2px 24px rgba(0,0,0,.18)}.hero-content h1 span{display:inline-block}.hero-content h1 em{font-size:.52em;color:var(--accent-soft);font-weight:400;margin:0 .13em}.hero-rule{display:flex;align-items:center;width:min(460px,68vw);gap:14px;margin:28px auto 12px;color:var(--accent-soft)}.hero-rule span{height:1px;background:currentColor;flex:1}.hero-rule i{font-style:normal;font-size:12px}.date{font-family:var(--serif);font-size:14px;letter-spacing:.12em}.primary-button{margin-top:22px;padding:14px 25px;border:1px solid var(--accent-soft);text-decoration:none;text-transform:uppercase;letter-spacing:.18em;font-size:9px;background:rgba(7,27,20,.24)}.scroll-cue{position:absolute;z-index:2;bottom:25px;left:4.5%;font-size:9px;letter-spacing:.22em;text-transform:uppercase;text-decoration:none}.scroll-cue span{margin-left:10px;color:var(--accent-soft)}\nsection{padding:110px 7%}.welcome{text-align:center;max-width:1150px;margin:auto}.section-kicker{color:var(--accent);margin:0 0 18px}.welcome h2,.story h2,.details h2,.gallery h2,.travel h2,.faq h2,.rsvp h2{font-family:var(--serif);font-weight:400;font-size:clamp(42px,6vw,78px);line-height:1.02;letter-spacing:-.035em;margin:0}.intro{max-width:650px;margin:30px auto 55px;color:var(--muted);line-height:1.9;font-family:var(--serif);font-size:17px}.mini-details{border-top:1px solid var(--line);border-bottom:1px solid var(--line);display:grid;grid-template-columns:repeat(3,1fr);padding:28px 0}.mini-details div+div{border-left:1px solid var(--line)}.mini-details span,.travel-list span{font-family:var(--serif);color:var(--accent);font-style:italic}.mini-details h3{font-family:var(--serif);font-weight:400;margin:7px 0 2px}.mini-details p{font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin:0}\n.story{display:grid;grid-template-columns:minmax(280px,.8fr) 1.2fr;gap:8vw;align-items:center;background:var(--surface)}.frame{position:relative;padding:18px;border:1px solid var(--accent)}.frame:before,.frame:after{content:'';position:absolute;width:60px;height:60px;border-color:var(--accent)}.frame:before{left:-8px;top:-8px;border-left:1px solid;border-top:1px solid}.frame:after{right:-8px;bottom:-8px;border-right:1px solid;border-bottom:1px solid}.story-image{height:680px}.story-copy>p:not(.section-kicker):not(.edit-note){max-width:610px;color:var(--muted);font-family:var(--serif);font-size:17px;line-height:1.8}.timeline{margin-top:45px;border-left:1px solid var(--accent);padding-left:30px;display:grid;gap:25px}.timeline span{font-size:9px;letter-spacing:.18em;color:var(--accent);text-transform:uppercase}.timeline h3{font-family:var(--serif);font-weight:400;font-size:22px;margin:3px 0}.timeline p{margin:0;color:var(--muted);font-size:12px}.edit-note{display:inline-block;margin-top:32px;padding:9px 13px;border:1px dashed var(--line);font-size:10px;color:var(--muted)}\n.details{text-align:center;background:var(--deep);color:#f9f1df}.detail-cards{display:grid;grid-template-columns:repeat(3,1fr);max-width:1200px;margin:55px auto 0;border:1px solid rgba(255,255,255,.2)}.detail-cards article{padding:50px 28px}.detail-cards article+article{border-left:1px solid rgba(255,255,255,.2)}.card-number{font-family:var(--serif);font-style:italic;color:var(--accent-soft)}.detail-cards h3{font-family:var(--serif);font-size:28px;font-weight:400;margin:17px}.card-time{text-transform:uppercase;letter-spacing:.18em;font-size:9px;color:var(--accent-soft)}.detail-cards article>p:not(.card-time){font-family:var(--serif);color:rgba(255,255,255,.7);line-height:1.7}.detail-cards small{text-transform:uppercase;letter-spacing:.15em;font-size:8px}.quote-band{padding:85px 7%;text-align:center;background:var(--accent);color:var(--deep)}.quote-band p{font-family:var(--serif);font-style:italic;font-size:clamp(26px,4vw,50px);margin:0 0 12px}.quote-band span{font-size:9px;letter-spacing:.2em;text-transform:uppercase}\n.gallery{max-width:1300px;margin:auto}.gallery-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:45px}.gallery-heading>p{color:var(--muted);font-family:var(--serif);font-style:italic}.photo-grid{display:grid;grid-template-columns:1.3fr .7fr;grid-template-rows:410px 260px;gap:18px}.photo-grid figure{margin:0;position:relative;overflow:hidden}.photo-main{grid-row:1/3}.photo-grid figure img{transition:transform .7s}.photo-grid figure:hover img{transform:scale(1.02)}.photo-grid figcaption{position:absolute;bottom:0;left:0;right:0;padding:35px 20px 18px;background:linear-gradient(transparent,rgba(0,0,0,.6));color:white;font-family:var(--serif);font-style:italic}.gallery-card{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border:1px solid var(--line)}.gallery-card span{font-family:var(--serif);font-size:55px;color:var(--accent)}.gallery-card p{font-size:10px;letter-spacing:.16em;text-transform:uppercase;line-height:1.8}\n.travel{display:grid;grid-template-columns:1fr 1fr;gap:9vw;background:var(--surface)}.travel-copy>p:not(.section-kicker){font-family:var(--serif);color:var(--muted);line-height:1.8;max-width:550px}.text-link{text-transform:uppercase;letter-spacing:.15em;font-size:9px;text-decoration:none;border-bottom:1px solid var(--accent);padding-bottom:8px}.text-link span{margin-left:8px}.travel-list{border-top:1px solid var(--line)}.travel-list div{display:grid;grid-template-columns:50px 1fr;align-items:center;padding:22px 0;border-bottom:1px solid var(--line)}.travel-list h3{font-family:var(--serif);font-weight:400;margin:0}.travel-list p{grid-column:2;margin:3px 0;color:var(--muted);font-size:11px}\n.faq{text-align:center}.faq-grid{max-width:1000px;margin:45px auto 0;display:grid;grid-template-columns:1fr 1fr;text-align:left}.faq-grid div{padding:30px;border-top:1px solid var(--line)}.faq-grid div:nth-child(even){border-left:1px solid var(--line)}.faq-grid h3{font-family:var(--serif);font-weight:400;font-size:22px}.faq-grid p{font-family:var(--serif);color:var(--muted);line-height:1.7}.rsvp{background:var(--deep);color:#fff;text-align:center}.rsvp-inner{max-width:740px;margin:auto}.rsvp-inner>p:not(.section-kicker):not(.deadline){font-family:var(--serif);line-height:1.8;color:rgba(255,255,255,.7)}.sheet-placeholder{margin:40px auto 22px;padding:34px;border:1px dashed var(--accent-soft);display:flex;flex-direction:column;gap:9px;background:rgba(255,255,255,.04)}.sheet-placeholder span{font-family:var(--serif);font-size:21px;color:var(--accent-soft)}.sheet-placeholder small{font-size:9px;letter-spacing:.12em;text-transform:uppercase}.deadline{font-size:9px;letter-spacing:.18em;text-transform:uppercase}footer{padding:45px 7% 100px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;background:#081c15;color:#fff;border-top:1px solid rgba(255,255,255,.15)}footer p{font-size:9px;letter-spacing:.15em;text-transform:uppercase}.footer-note{text-align:right;color:rgba(255,255,255,.5)}\nbody[data-theme=\"noir\"]{--bg:#f7f6f2;--surface:#fff;--ink:#111;--muted:#626262;--accent:#111;--accent-soft:#fff;--deep:#0b0b0b;--line:rgba(0,0,0,.2);--hero-position:center 35%}body[data-theme=\"noir\"] .hero-photo{filter:grayscale(1) contrast(1.06)}body[data-theme=\"noir\"] .quote-band{color:#fff}body[data-theme=\"noir\"] .frame{padding:0;border-width:8px}body[data-theme=\"noir\"] .hero-content h1{text-transform:uppercase;font-size:clamp(54px,9vw,125px);letter-spacing:.02em}body[data-theme=\"noir\"] .hero-content h1 em{font-size:.35em;color:#fff}\nbody[data-theme=\"sage\"]{--bg:#f8f4ec;--surface:#efe7da;--ink:#465143;--muted:#767b70;--accent:#a38358;--accent-soft:#ecd9bc;--deep:#66725f;--line:rgba(70,81,67,.23);--hero-position:center 35%}body[data-theme=\"sage\"] .hero-shade{background:linear-gradient(180deg,rgba(44,54,42,.42),rgba(30,38,29,.05) 42%,rgba(44,54,42,.58))}body[data-theme=\"sage\"] .detail-cards{border-radius:160px 160px 0 0;overflow:hidden}body[data-theme=\"sage\"] .primary-button{background:rgba(244,234,218,.14)}\n@media(max-width:800px){.concept-picker{width:calc(100% - 20px);bottom:10px;flex-direction:column;gap:3px;border-radius:18px;padding:8px}.picker-label{display:none}.picker-buttons{width:100%}.picker-buttons button{flex:1;justify-content:center}.picker-buttons button span{font-size:9px}.nav-links{display:none}.top-nav{padding:19px 22px}.hero{min-height:640px}.hero-content h1 span{display:block}.hero-content h1 em{display:block;margin:.18em}.hero-content h1{line-height:.72}.date{font-size:12px}.welcome,.details,.gallery,.travel,.faq,.rsvp{padding:80px 24px}.mini-details{grid-template-columns:1fr;gap:0}.mini-details div{padding:18px}.mini-details div+div{border-left:0;border-top:1px solid var(--line)}.story{grid-template-columns:1fr;padding:80px 24px}.story-image{height:520px}.detail-cards{grid-template-columns:1fr}.detail-cards article+article{border-left:0;border-top:1px solid rgba(255,255,255,.2)}.gallery-heading{display:block}.photo-grid{display:grid;grid-template-columns:1fr;grid-template-rows:500px 420px 220px}.photo-main{grid-row:auto}.travel{grid-template-columns:1fr}.faq-grid{grid-template-columns:1fr}.faq-grid div:nth-child(even){border-left:0}footer{grid-template-columns:1fr;text-align:center;gap:10px}.footer-note{text-align:center}}\n</style>\n</head>\n<body data-theme=\"emerald\">\n  <aside class=\"concept-picker\" aria-label=\"Choose a wedding website concept\">\n    <span class=\"picker-label\">View concept</span>\n    <div class=\"picker-buttons\" role=\"group\" aria-label=\"Color concept\">\n      <button type=\"button\" data-set-theme=\"noir\"><i class=\"swatch noir\"></i><span>Black & White</span></button>\n      <button type=\"button\" data-set-theme=\"emerald\" class=\"active\"><i class=\"swatch emerald\"></i><span>Gold & Green</span></button>\n      <button type=\"button\" data-set-theme=\"sage\"><i class=\"swatch sage\"></i><span>Sage & Champagne</span></button>\n    </div>\n  </aside>\n\n  <header class=\"hero\" id=\"home\">\n    <nav class=\"top-nav\" aria-label=\"Main navigation\">\n      <a class=\"monogram\" href=\"#home\" aria-label=\"Wilda and Sean Walker home\">W <b>&</b> S</a>\n      <div class=\"nav-links\">\n        <a href=\"#story\">Our Story</a><a href=\"#details\">Details</a><a href=\"#gallery\">Photos</a><a href=\"#travel\">Travel</a>\n      </div>\n      <a class=\"nav-rsvp\" href=\"#rsvp\">RSVP</a>\n    </nav>\n    <div class=\"hero-photo\" role=\"img\" aria-label=\"Wilda and Sean Walker dressed for an elegant evening\"></div>\n    <div class=\"hero-shade\"></div>\n    <div class=\"hero-content\">\n      <p class=\"eyebrow\">A night of love, music & forever</p>\n      <h1><span>Wilda</span><em>&</em><span>Sean</span></h1>\n      <div class=\"hero-rule\"><span></span><i>✦</i><span></span></div>\n      <p class=\"date\">Saturday, September 19, 2027 · South Florida</p>\n      <a class=\"primary-button\" href=\"#details\">Join us for the evening</a>\n    </div>\n    <a class=\"scroll-cue\" href=\"#welcome\" aria-label=\"Continue to welcome section\">Scroll <span>↓</span></a>\n  </header>\n\n  <main>\n    <section class=\"welcome\" id=\"welcome\">\n      <p class=\"section-kicker\">The feature presentation</p>\n      <h2>Our greatest night<br>is better with you.</h2>\n      <p class=\"intro\">The lights are low, the band is warm, and our favorite people are gathering. Join us for a wedding celebration inspired by jazz-club romance and the timeless glamour of opening night.</p>\n      <div class=\"mini-details\" aria-label=\"Wedding overview\">\n        <div><span>01</span><h3>The Date</h3><p>September 19, 2027</p></div>\n        <div><span>02</span><h3>The Place</h3><p>South Florida</p></div>\n        <div><span>03</span><h3>The Mood</h3><p>Black tie · Jazz night</p></div>\n      </div>\n    </section>\n\n    <section class=\"story\" id=\"story\">\n      <div class=\"story-image frame\"><img src=\"data:image/jpeg;base64,\" alt=\"Wilda and Sean Walker smiling together\"></div>\n      <div class=\"story-copy\">\n        <p class=\"section-kicker\">Long story short</p>\n        <h2>One beautiful story,<br>still being written.</h2>\n        <p>Every great love has a first scene, a favorite chapter, and a moment when everything changes. Ours led us here—to a room filled with music, laughter, and all of you.</p>\n        <div class=\"timeline\">\n          <div><span>Act I</span><h3>First Met</h3><p>Where the story began</p></div>\n          <div><span>Act II</span><h3>First “I Love You”</h3><p>The unforgettable line</p></div>\n          <div><span>Act III</span><h3>The Proposal</h3><p>Our favorite yes</p></div>\n        </div>\n        <p class=\"edit-note\">Dates and story details can be added here.</p>\n      </div>\n    </section>\n\n    <section class=\"details\" id=\"details\">\n      <p class=\"section-kicker\">Tonight’s program</p>\n      <h2>The Wedding Details</h2>\n      <div class=\"detail-cards\">\n        <article><span class=\"card-number\">I</span><h3>The Ceremony</h3><p class=\"card-time\">5:30 in the evening</p><p>Venue name and address<br>South Florida</p><small>Doors open at 5:00</small></article>\n        <article><span class=\"card-number\">II</span><h3>Cocktails & Jazz</h3><p class=\"card-time\">6:00 in the evening</p><p>Champagne, conversation<br>& a live quartet</p><small>Black-tie attire</small></article>\n        <article><span class=\"card-number\">III</span><h3>The Reception</h3><p class=\"card-time\">7:00 until late</p><p>Dinner, dancing<br>& an encore or two</p><small>Adults-only celebration</small></article>\n      </div>\n    </section>\n\n    <section class=\"quote-band\"><p>“Life is a lot like jazz… it’s best when you improvise.”</p><span>— George Gershwin</span></section>\n\n    <section class=\"gallery\" id=\"gallery\">\n      <div class=\"gallery-heading\"><div><p class=\"section-kicker\">A few favorite frames</p><h2>In Pictures</h2></div><p>Love, laughter, and a little old-Hollywood magic.</p></div>\n      <div class=\"photo-grid\">\n        <figure class=\"photo-main\"><img src=\"data:image/jpeg;base64,\" alt=\"Wilda and Sean Walker posing on tiled stairs\"><figcaption>Our leading roles</figcaption></figure>\n        <figure><img src=\"data:image/jpeg;base64,\" alt=\"Wilda and Sean Walker beneath elegant arches\"><figcaption>Golden hour</figcaption></figure>\n        <div class=\"gallery-card\"><span>W & S</span><p>More photographs<br>can be added here.</p></div>\n      </div>\n    </section>\n\n    <section class=\"travel\" id=\"travel\">\n      <div class=\"travel-copy\"><p class=\"section-kicker\">Make a weekend of it</p><h2>Travel & Stay</h2><p>We can’t wait to welcome you. This section can include the hotel block, airport suggestions, transportation notes, and a few favorite places to eat, sip, and explore.</p><a href=\"#\" class=\"text-link\" onclick=\"return false\">Travel guide coming soon <span>→</span></a></div>\n      <div class=\"travel-list\">\n        <div><span>01</span><h3>Hotel</h3><p>Room block details go here</p></div>\n        <div><span>02</span><h3>Getting Here</h3><p>Airport and shuttle notes</p></div>\n        <div><span>03</span><h3>Things To Do</h3><p>Our favorite local spots</p></div>\n      </div>\n    </section>\n\n    <section class=\"faq\">\n      <p class=\"section-kicker\">The fine print</p><h2>Questions & Answers</h2>\n      <div class=\"faq-grid\"><div><h3>What should I wear?</h3><p>Black-tie attire. Think timeless evening glamour, polished silhouettes, and dancing shoes.</p></div><div><h3>May I bring a guest?</h3><p>Your invitation will note the guests included in your party.</p></div><div><h3>Are children invited?</h3><p>We’re planning an adults-only evening so everyone can enjoy the late-night celebration.</p></div><div><h3>Where are you registered?</h3><p>A registry link and short note can be placed here once ready.</p></div></div>\n    </section>\n\n    <section class=\"rsvp\" id=\"rsvp\">\n      <div class=\"rsvp-inner\"><p class=\"section-kicker\">Kindly reply</p><h2>Will you join us?</h2><p>We hope you’ll be there for the first note, the last dance, and every beautiful moment in between.</p><div class=\"sheet-placeholder\"><span>Google Sheet RSVP goes here</span><small>Form integration will be added after the design is selected.</small></div><p class=\"deadline\">Please reply by August 1, 2027</p></div>\n    </section>\n  </main>\n\n  <footer><a class=\"monogram\" href=\"#home\">W <b>&</b> S</a><p>Wilda & Sean Walker · September 19, 2027</p><p class=\"footer-note\">The Walkers · Made with love, rhythm & a little champagne.</p></footer>\n  <script>const buttons = document.querySelectorAll('[data-set-theme]');\nconst themeNames = { noir: 'Traditional black and white', emerald: 'Gold and green', sage: 'Sage, champagne and white' };\n\nbuttons.forEach((button) => {\n  button.addEventListener('click', () => {\n    const theme = button.dataset.setTheme;\n    document.body.dataset.theme = theme;\n    buttons.forEach((item) => item.classList.toggle('active', item === button));\n    document.title = `${themeNames[theme]} — Wilda & Sean Walker`;\n  });\n});\n</script>\n</body>\n</html>\n";
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== '/' && url.pathname !== '/index.html') {
      return new Response('Not found', { status: 404 });
    }
    return new Response(page, {
      headers: {
        'content-type': 'text/html; charset=UTF-8',
        'cache-control': 'public, max-age=300',
        'x-content-type-options': 'nosniff'
      }
    });
  }
};
